                "text": "import dayjs from 'dayjs';\nimport { useState } from 'react';\nimport { FormControl, InputLabel, Select, MenuItem, useTheme } from '@mui/material';\nimport {\n  Brush,\n  CartesianGrid,\n  Line,\n  LineChart,\n  ResponsiveContainer,\n  Tooltip,\n  XAxis,\n  YAxis,\n} from 'recharts';\nimport ReportFilter from './components/ReportFilter';\nimport { formatTime } from '../common/util/formatter';\nimport { useTranslation } from '../common/components/LocalizationProvider';\nimport PageLayout from '../common/components/PageLayout';\nimport ReportsMenu from './components/ReportsMenu';\nimport usePositionAttributes from '../common/attributes/usePositionAttributes';\nimport { useCatchCallback } from '../reactHelper';\nimport { useAttributePreference } from '../common/util/preferences';\nimport {\n  altitudeFromMeters,\n  distanceFromMeters,\n  speedFromKnots,\n  speedToKnots,\n  volumeFromLiters,\n} from '../common/util/converter';\nimport useReportStyles from './common/useReportStyles';\nimport fetchOrThrow from '../common/util/fetchOrThrow';\n\nconst ChartReportPage = () => {\n  const { classes } = useReportStyles();\n  const theme = useTheme();\n  const t = useTranslation();\n\n  const positionAttributes = usePositionAttributes(t);\n\n  const distanceUnit = useAttributePreference('distanceUnit');\n  const altitudeUnit = useAttributePreference('altitudeUnit');\n  const speedUnit = useAttributePreference('speedUnit');\n  const volumeUnit = useAttributePreference('volumeUnit');\n\n  const [items, setItems] = useState([]);\n  const [types, setTypes] = useState(['speed']);\n  const [selectedTypes, setSelectedTypes] = useState(['speed']);\n  const [timeType, setTimeType] = useState('fixTime');\n\n  const values = items\n    .map((it) => selectedTypes.map((type) => it[type]).filter((value) => value != null))\n    .flat();\n  const minValue = values.length ? Math.min(...values) : 0;\n  const maxValue = values.length ? Math.max(...values) : 100;\n  const valueRange = maxValue - minValue;\n\n  const onShow = useCatchCallback(\n    async ({ deviceIds, from, to }) => {\n      const query = new URLSearchParams({ from, to });\n      deviceIds.forEach((deviceId) => query.append('deviceId', deviceId));\n      const response = await fetchOrThrow(`/api/reports/route?${query.toString()}`, {\n        headers: { Accept: 'application/json' },\n      });\n      const positions = await response.json();\n      const keySet = new Set();\n      const keyList = [];\n      const formattedPositions = positions.map((position) => {\n        const data = { ...position, ...position.attributes };\n        const formatted = {};\n        formatted.fixTime = dayjs(position.fixTime).valueOf();\n        formatted.deviceTime = dayjs(position.deviceTime).valueOf();\n        formatted.serverTime = dayjs(position.serverTime).valueOf();\n        Object.keys(data)\n          .filter((key) => !['id', 'deviceId'].includes(key))\n          .forEach((key) => {\n            const value = data[key];\n            if (typeof value === 'number') {\n              keySet.add(key);\n              const definition = positionAttributes[key] || {};\n              switch (definition.dataType) {\n                case 'speed':\n                  if (key == 'obdSpeed') {\n                    formatted[key] = speedFromKnots(speedToKnots(value, 'kmh'), speedUnit).toFixed(\n                      2,\n                    );\n                  } else {\n                    formatted[key] = speedFromKnots(value, speedUnit).toFixed(2);\n                  }\n                  break;\n                case 'altitude':\n                  formatted[key] = altitudeFromMeters(value, altitudeUnit).toFixed(2);\n                  break;\n                case 'distance':\n                  formatted[key] = distanceFromMeters(value, distanceUnit).toFixed(2);\n                  break;\n                case 'volume':\n                  formatted[key] = volumeFromLiters(value, volumeUnit).toFixed(2);\n                  break;\n                case 'hours':\n                  formatted[key] = (value / 1000).toFixed(2);\n                  break;\n                default:\n                  formatted[key] = value;\n                  break;\n              }\n            }\n          });\n        return formatted;\n      });\n      Object.keys(positionAttributes).forEach((key) => {\n        if (keySet.has(key)) {\n          keyList.push(key);\n          keySet.delete(key);\n        }\n      });\n      setTypes([...keyList, ...keySet]);\n      setItems(formattedPositions);\n    },\n    [positionAttributes, speedUnit, altitudeUnit, distanceUnit, volumeUnit],\n  );\n\n  const colorPalette = [\n    theme.palette.primary.main,\n    theme.palette.secondary.main,\n    theme.palette.error.main,\n    theme.palette.warning.main,\n    theme.palette.info.main,\n    theme.palette.success.main,\n    theme.palette.text.secondary,\n  ];\n\n  return (\n    <PageLayout menu={<ReportsMenu />} breadcrumbs={['reportTitle', 'reportChart']}>\n      <ReportFilter onShow={onShow} onExport={() => {}} deviceType=\"single\" formats={[]}>\n        <div className={classes.filterItem}>\n          <FormControl fullWidth>\n            <InputLabel>{t('reportChartType')}</InputLabel>\n            <Select\n              label={t('reportChartType')}\n              value={selectedTypes}\n              onChange={(e) => setSelectedTypes(e.target.value)}\n              multiple\n              disabled={!items.length}\n            >\n              {types.map((key) => (\n                <MenuItem key={key} value={key}>\n                  {positionAttributes[key]?.name || key}\n                </MenuItem>\n              ))}\n            </Select>\n          </FormControl>\n        </div>\n        <div className={classes.filterItem}>\n          <FormControl fullWidth>\n            <InputLabel>{t('reportTimeType')}</InputLabel>\n            <Select\n              label={t('reportTimeType')}\n              value={timeType}\n              onChange={(e) => setTimeType(e.target.value)}\n              disabled={!items.length}\n            >\n              <MenuItem value=\"fixTime\">{t('positionFixTime')}</MenuItem>\n              <MenuItem value=\"deviceTime\">{t('positionDeviceTime')}</MenuItem>\n              <MenuItem value=\"serverTime\">{t('positionServerTime')}</MenuItem>\n            </Select>\n          </FormControl>\n        </div>\n      </ReportFilter>\n      {items.length > 0 && (\n        <div className={classes.chart}>\n          <ResponsiveContainer>\n            <LineChart\n              data={items}\n              margin={{\n                top: 10,\n                right: 40,\n                left: 10,\n                bottom: 10,\n              }}\n            >\n              <XAxis\n                stroke={theme.palette.text.primary}\n                dataKey={timeType}\n                type=\"number\"\n                tickFormatter={(value) => formatTime(value, 'time')}\n                domain={['dataMin', 'dataMax']}\n                scale=\"time\"\n              />\n              <YAxis\n                stroke={theme.palette.text.primary}\n                type=\"number\"\n                tickFormatter={(value) => parseFloat(value.toFixed(2))}\n                domain={[minValue - valueRange / 5, maxValue + valueRange / 5]}\n              />\n              <CartesianGrid stroke={theme.palette.divider} strokeDasharray=\"3 3\" />\n              <Tooltip\n                contentStyle={{\n                  backgroundColor: theme.palette.background.default,\n                  color: theme.palette.text.primary,\n                }}\n                formatter={(value, key) => [value, positionAttributes[key]?.name || key]}\n                labelFormatter={(value) => formatTime(value, 'seconds')}\n              />\n              <Brush\n                dataKey={timeType}\n                height={30}\n                stroke={theme.palette.primary.main}\n     